variante_1.css:
.sl-author-widget .sl-author-avatar {
  width: 90px;
  height: 90px;
  border-radius: 50%;
  border: 3px solid var(--sl-primary);
  transition: transform 0.3s ease-in-out;
}
.sl-author-widget .sl-author-avatar:hover {
  transform: scale(1.05);
}
.sl-author-widget .sl-social-links .sl-social-icon {
  color: var(--sl-text-main);
  font-size: 1.5rem;
  transition: color 0.3s ease-in-out, transform 0.3s ease-in-out;
}
.sl-author-widget .sl-social-links .sl-social-icon:hover {
  color: var(--sl-primary);
  transform: translateY(-3px);
}

variante_2.css:
.sl-tag-cloud-widget .badge {
  padding: 0.4em 0.8em;
  border-radius: 0.25rem;
  transition: all 0.3s ease-in-out;
  font-weight: normal;
}
.sl-tag-cloud-widget .badge:hover {
  transform: translateY(-2px) scale(1.05);
  opacity: 0.9;
}
.sl-tag-cloud-widget .sl-tag-sm {
  font-size: 0.8em;
}
.sl-tag-cloud-widget .sl-tag-md {
  font-size: 1em;
}
.sl-tag-cloud-widget .sl-tag-lg {
  font-size: 1.2em;
  font-weight: bold;
}
/* Custom Bootstrap background colors using CSS variables */
.text-bg-primary {
  background-color: var(--sl-primary) !important;
  color: #fff !important;
}
.text-bg-accent {
  background-color: var(--sl-accent) !important;
  color: var(--sl-text-main) !important; /* Ajuste se a cor de destaque for escura */
}

variante_3.css:
.sl-popular-posts-widget .list-group-item {
  background-color: transparent; /* Garante que respeite o background do card-body */
  border-color: var(--sl-border);
  padding-left: 2.5rem; /* Ajuste para o espaçamento da numeração */
}
.sl-popular-posts-widget .list-group-item::before {
  color: var(--sl-primary);
  font-weight: bold;
}
.sl-popular-posts-widget .sl-post-link {
  color: var(--sl-text-main);
  transition: color 0.3s ease-in-out;
}
.sl-popular-posts-widget .sl-post-link:hover {
  color: var(--sl-primary);
}
.sl-popular-posts-widget .sl-list-item-custom {
  background-color: var(--sl-card-bg);
}
.sl-popular-posts-widget .sl-list-item-custom:hover {
  background-color: rgba(var(--sl-primary-rgb), 0.1); /* Efeito de hover suave */
  cursor: pointer;
}

variante_4.css:
.sl-ad-widget .sl-ad-placeholder {
  width: 300px;
  height: 250px;
  background-color: var(--sl-bg-body);
  border-color: var(--sl-border) !important;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  color: var(--sl-text-main);
}
